with flattened as (select id, level, latency_ms, k, attr_value from app_logs lateral view outer explode(context) e as k, attr_value) select *, dense_rank() over w_ordered as latency_ms_dense_rank, round(latency_ms / sum(latency_ms) over (partition by level), 4) as latency_ms_share, round(latency_ms / sum(latency_ms) over (partition by k), 4) as latency_ms_share_2, round(latency_ms / sum(latency_ms) over (partition by level), 4) as latency_ms_share_3 from flattened window w_ordered as (partition by level order by latency_ms)
